function activeNeed(){return G.clientNeeds.find(x=>x.needId===G.activeNeedId)||null}
function needBucket(name){let id=G.activeNeedId;if(!id)return[];G[name]=G[name]||{};return G[name][id]=G[name][id]||[]}
function startNeed(id){G.activeNeedId=id;G.need=activeNeed();G.needDraft=null;persist(true);go(22)}
function editNeed(id){let n=G.clientNeeds.find(x=>x.needId===id);if(!n)return;G.activeNeedId=id;G.need=n;G.needDraft={...n};persist(true);go(21)}
function newNeed(){if(!clientAuthorize('إنشاء الاحتياجات'))return;G.needDraft={clientAccountId:G.activeClientAccountId,outputType:''};G.activeNeedId='';persist(true);go(21)}
function saveNeed(asDraft=false){let v=G.needDraft||{};
  if(!asDraft&&(!v.title||!v.outputType||!v.service||!v.current||!v.target)){toast('أكمل الحقول الإلزامية');return}
  let outputMissing=needOutputMissing(v);if(!asDraft&&outputMissing){toast('أكمل: '+outputMissing);return}
  let id=v.needId||'NEED-'+String(Date.now()).slice(-8),old=G.clientNeeds.findIndex(x=>x.needId===id);
  let rec={...v,clientAccountId:v.clientAccountId||G.activeClientAccountId,needId:id,status:asDraft?'مسودة':(v.status||'جاهز للمراجعة'),published:!!v.published,createdAt:v.createdAt||Date.now(),updatedAt:Date.now()};
  if(old<0)G.clientNeeds.push(rec);else G.clientNeeds[old]=rec;G.activeNeedId=id;G.need=rec;G.needDraft=null;persist(true);
  if(asDraft){go(20);toast('حُفظت مسودة الاحتياج')}else{go(22);toast('حُفظ الاحتياج — أكمل بصمة المهمة والأوزان')}}
function clientProfileHealth(a){
  if(!a)return{pct:0,missing:['إنشاء ملف الجهة']};
  let checks=[['الاسم القانوني',a.legalNameAr],['الاسم الإنجليزي',a.legalNameEn],['رقم التسجيل',a.registrationNo],['الرقم الضريبي',a.taxNo],['الدولة',a.country],['قطاع الجهة',a.sector],['البريد الإلكتروني',a.email],['الهاتف',a.phone],['العنوان',a.address],['ممثل رئيسي',G.clientRepresentatives.some(x=>x.clientAccountId===a.clientAccountId&&x.primary&&x.active)],['ملف فوترة معتمد',G.clientBillingProfiles.some(x=>x.clientAccountId===a.clientAccountId&&x.status==='معتمد داخليًا')]];
  let done=checks.filter(x=>!!x[1]).length;return{pct:Math.round(done/checks.length*100),missing:checks.filter(x=>!x[1]).map(x=>x[0])}}
function clientCompletenessDimensions(a){
  let reps=G.clientRepresentatives.filter(x=>x.clientAccountId===a?.clientAccountId&&x.active),billing=G.clientBillingProfiles.find(x=>x.clientAccountId===a?.clientAccountId),hasPrimary=reps.some(x=>x.primary),hasAuthorities=reps.some(x=>(x.authorities||[]).length>=3);
  let calc=(label,checks,detail)=>{let done=checks.filter(Boolean).length,pct=Math.round(done/Math.max(1,checks.length)*100);return{label,pct,detail,className:pct>=80?'good':pct>=50?'warn':''}};
  let data=calc('البيانات',[a?.legalNameAr,a?.legalNameEn,a?.type,a?.country,a?.city,a?.sector,a?.email,a?.phone,a?.address],'الهوية والتواصل');
  let docs=calc('الوثائق',[a?.registrationNo,a?.taxNo,a?.website,billing?.taxNo,billing?.address],'السجل والفوترة');
  let verified=calc('التحقق',[a?.verification&&a.verification!=='غير متحقق',a?.status==='نشط',a?.email,a?.registrationNo],'حالة الاعتماد');
  let auth=calc('الصلاحيات',[reps.length>0,hasPrimary,hasAuthorities,reps.some(x=>Number(x.approvalLimit)>0),reps.some(x=>x.authorizationExpiry)],'الممثلون والتفويض');
  let ready=calc('الجاهزية',[data.pct>=75,docs.pct>=60,verified.pct>=50,auth.pct>=60,billing?.status==='معتمد داخليًا'],'جاهزية التعامل');
  return[data,docs,verified,auth,ready]}
function completionDimensionHtml(d){return `<div class="completion-item ${d.className}"><div class="ctop"><span>${d.label}</span><b>${d.pct}%</b></div><div class="meter"><i style="width:${d.pct}%"></i></div><small title="${esc(d.detail)}">${esc(d.detail)}</small></div>`}
function clientRecentActivity(id){
  let out=[];
  G.clientInteractions.filter(x=>x.clientAccountId===id).forEach(x=>out.push({at:x.createdAt||new Date(x.date).getTime(),title:'تواصل: '+(x.subject||x.channel),meta:(x.channel||'')+' · '+(x.owner||'')}));
  G.clientNeeds.filter(x=>x.clientAccountId===id).forEach(x=>out.push({at:x.updatedAt||x.createdAt,title:'احتياج: '+(x.title||'مسودة'),meta:x.status||'مسودة'}));
  G.clientRequests.filter(x=>x.clientAccountId===id).forEach(x=>out.push({at:x.updatedAt||x.createdAt,title:'طلب خدمة: '+(x.subject||x.requestId),meta:x.status||'مسودة'}));
  G.clientGovernanceLog.filter(x=>x.clientAccountId===id).forEach(x=>out.push({at:x.at,title:x.action,meta:x.actor||'سجل الحوكمة'}));
  return out.sort((a,b)=>(b.at||0)-(a.at||0)).slice(0,5)}
