function weightSet(k,v){let fp=needFingerprint();if(!fp)return;fp.weights[k]=Math.max(0,Math.min(100,Number(v)||0));fp.status='مسودة';fp.updatedAt=Date.now();G.matchingWeights={...fp.weights};persist(true);let e=$('weightTotal');if(e)e.textContent=weightTotal()+'%'}
