function norm(s){return String(s||'').toLowerCase().replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/[^\u0600-\u06ff\w]+/g,' ').trim()}
function textScore(a,b){let A=new Set(norm(a).split(' ').filter(x=>x.length>2)),B=new Set(norm(b).split(' ').filter(x=>x.length>2));if(!A.size||!B.size)return 45;let hit=[...A].filter(x=>B.has(x)).length;return Math.min(100,Math.round(35+65*hit/Math.max(1,Math.min(A.size,B.size))))}
function stable(ref,min,max){let h=[...ref].reduce((s,c)=>(s*31+c.charCodeAt(0))%9973,7);return min+(h%(max-min+1))}
function directoryCandidates(){let out=[];Object.entries(SEARCH_DIRS||{}).forEach(([kind,M])=>(M.list||[]).forEach((x,i)=>out.push({ref:x.ref||`dir:${kind}:${i}`,partyId:x.partyId||null,kind,name:x.name,role:kind==='center'?'مركز / معهد تدريب':(x.title||x.inst||DIR_KIND_LABEL[kind]),main:x.main||x.spec,sub:x.sub||x.spec,country:x.country,langs:x.langs||[],rating:Number(x.rating)||0,verified:!!x.verified,extra:x.extra||'',sourceIndex:i})));return out}
function candidateByRef(ref){if(ref.startsWith('course:')){let key=ref.slice(7),x=courseOfferRows().find(y=>y.rowKey===key);return x?{ref,kind:'course',name:x.name,role:'دورة تدريبية',main:x.domain,sub:x.specialty,country:x.displayCountry,langs:[x.displayLanguage],rating:x.rating,verified:true,extra:[x.provider,x.trainer,x.mode].join(' · '),price:Number(x.displayPrice)||0,rowKey:key}:null}return directoryCandidates().find(x=>x.ref===ref)||null}
function poolForNeed(n){let kinds=/تدريب|ورشة|دورة/.test([n.service,n.title,n.current,n.target].join(' '))?['trainer','center']:n.outputType==='study'?['researcher','expert','consultant']:n.outputType==='consultation'?['consultant','expert','researcher']:n.outputType==='project'?['expert','consultant','center','trainer']:n.outputType==='product'?['expert','consultant','researcher','center']:['expert','consultant','researcher','trainer'];return directoryCandidates().filter(x=>kinds.includes(x.kind))}
function componentScores(c,n){let budget=Number(n.budget)||0,price=c.price||stable(c.ref,90,260),exp=stable(c.ref+'exp',65,98),avail=stable(c.ref+'avail',70,100);
  return{specialty:textScore([n.main,n.sub].join(' '),[c.main,c.sub].join(' ')),practice:textScore(n.practice,[c.role,c.extra].join(' ')),sector:textScore(n.current,[c.main,c.extra].join(' ')),evidence:c.verified?100:55,experience:exp,language:!n.language?85:(c.langs.includes(n.language)?100:35),country:!n.country?85:(c.country===n.country?100:45),availability:avail,price:!budget?75:(price<=budget?100:Math.max(20,Math.round(budget/price*100))),rating:Math.round((c.rating||3.5)/5*100)}}
function scoreCandidate(c,n,w){let scores=componentScores(c,n),fp=needFingerprint(n.needId),mandatory=fp?.mandatory||n.mandatory||['specialty'],failed=mandatory.filter(k=>(scores[k]||0)<60);
  if(fp?.verifiedOnly&&!c.verified)failed.push('verifiedOnly');if(Number(fp?.minimumRating||0)>Number(c.rating||0))failed.push('minimumRating');
  if(Number(fp?.minimumExperience||0)>0&&scores.experience<Math.min(95,50+Number(fp.minimumExperience)*3))failed.push('minimumExperience');
  failed=[...new Set(failed)];let sum=MATCH_CRITERIA.reduce((s,x)=>s+(scores[x[0]]||0)*(Number(w[x[0]])||0),0)/100;
  let contributions={};MATCH_CRITERIA.forEach(x=>contributions[x[0]]=Math.round((scores[x[0]]||0)*(Number(w[x[0]])||0)/100));
  return{...c,score:Math.round(sum),scores,contributions,eligible:!failed.length,failed,strengths:MATCH_CRITERIA.filter(x=>scores[x[0]]>=85).sort((a,b)=>scores[b[0]]-scores[a[0]]).slice(0,3).map(x=>x[1]),gaps:MATCH_CRITERIA.filter(x=>scores[x[0]]<60).map(x=>x[1])}}
async function runWeightedMatching(){let n=activeNeed(),fp=needFingerprint();if(!n){toast('اختر احتياجًا أولًا');go(20);return}if(weightTotal()!==100){toast('يجب أن يساوي مجموع الأوزان 100%');go(23);return}
  let w={...(fp?.weights||G.matchingWeights)},results=poolForNeed(n).map(c=>scoreCandidate(c,n,w)).sort((a,b)=>(b.eligible-a.eligible)||(b.score-a.score));
  let run={runId:'MATCH-'+String(Date.now()).slice(-9),needId:n.needId,fingerprintId:fp?.fingerprintId||'',fingerprintVersion:fp?.version||1,fingerprintSnapshot:fp?needFingerprintSnapshot(fp):null,weights:w,mandatory:[...(fp?.mandatory||n.mandatory||[])],results,createdAt:Date.now(),serverValidated:false};G.matchingRuns.push(run);G.activeMatchRunId=run.runId;persist(true);
  if(typeof fetch!=='function'){go(25);toast('اكتملت المطابقة الموزونة وفق نسخة بصمة الاحتياج');return}
  try{let response=await fetch('/api/matching-runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(run)});let result=await response.json();if(!response.ok)throw new Error(result.error||'validation failed');run.serverValidated=true;run.serverValidatedAt=Date.now();run.serverResultCount=result.results?.length||0;persist(true);go(25);toast('اكتملت المطابقة واعتمد الخادم الأوزان والنتائج')}
  catch(error){console.warn('[EIM matching run]',error);go(25);toast('ظهرت النتائج محليًا، وتعذر اعتماد تشغيل المطابقة في الخادم')}}
function activeRun(){return G.matchingRuns.find(x=>x.runId===G.activeMatchRunId&&x.needId===G.activeNeedId)||[...G.matchingRuns].reverse().find(x=>x.needId===G.activeNeedId)||null}
