function toggleCandidate(bucket,ref,max){let a=needBucket(bucket),i=a.indexOf(ref);if(i>=0)a.splice(i,1);else if(max&&a.length>=max){toast('يمكن مقارنة أربعة خيارات كحد أقصى');return}else a.push(ref);persist(true);render()}
