function visualCompareRow(label,list,getter,opts={}){
  let vals=list.map(getter),norm=vals.map(v=>String(v?.display??v??'—').trim()),same=new Set(norm).size<=1,numbers=vals.map(v=>typeof v==='object'?Number(v.raw):Number(v)),valid=numbers.every(Number.isFinite),best=valid?(opts.lower?Math.min(...numbers):Math.max(...numbers)):null;
  return `<tr class="${same?'same-row':''}"><td><b>${esc(label)}</b>${opts.weight!=null?`<small style="display:block;color:var(--muted)">وزن العميل ${opts.weight}%</small>`:''}</td>${vals.map((v,i)=>{let display=typeof v==='object'?v.display:v,isBest=valid&&numbers[i]===best&&!same;return`<td class="${isBest?'best':''}">${esc(display??'—')}</td>`}).join('')}</tr>`}
